(function(){'use strict';const LANG_STORAGE_KEY='tdv_lang';const CONSENT_KEY='cookie_consent_status';const LANGUAGES=[{code:'en',flag:'\uD83C\uDDEC\uD83C\uDDE7',name:'English'},{code:'fr',flag:'\uD83C\uDDEB\uD83C\uDDF7',name:'Français'},{code:'de',flag:'\uD83C\uDDE9\uD83C\uDDEA',name:'Deutsch'},{code:'pt',flag:'\uD83C\uDDF5\uD83C\uDDF9',name:'Português'},{code:'sv',flag:'\uD83C\uDDF8\uD83C\uDDEA',name:'Svenska'},{code:'da',flag:'\uD83C\uDDE9\uD83C\uDDF0',name:'Dansk'},{code:'th',flag:'\uD83C\uDDF9\uD83C\uDDED',name:'ภาษาไทย'},{code:'zh-Hans',flag:'\uD83C\uDDE8\uD83C\uDDF3',name:'简体中文'},{code:'es',flag:'\uD83C\uDDEA\uD83C\uDDF8',name:'Español'},{code:'it',flag:'\uD83C\uDDEE\uD83C\uDDF9',name:'Italiano'},{code:'ru',flag:'\uD83C\uDDF7\uD83C\uDDFA',name:'Русский'},{code:'uk',flag:'\uD83C\uDDFA\uD83C\uDDE6',name:'Українська'},{code:'nl',flag:'\uD83C\uDDF3\uD83C\uDDF1',name:'Nederlands'},{code:'id',flag:'\uD83C\uDDEE\uD83C\uDDE9',name:'Bahasa Indonesia'},{code:'ko',flag:'\uD83C\uDDF0\uD83C\uDDF7',name:'한국어'},{code:'ja',flag:'\uD83C\uDDEF\uD83C\uDDF5',name:'日本語'}];const LANG_CODES=LANGUAGES.map(function(l){return l.code});var ENGLISH_ONLY_PATHS=['/privacy-policy/','/terms/','/pricing-policy/','/privacy-verification/'];function isEnglishOnlyPage(){var path=window.location.pathname;for(var i=0;i<ENGLISH_ONLY_PATHS.length;i++){if(path.indexOf(ENGLISH_ONLY_PATHS[i])===0){return true}}return false}function detectCurrentLang(){var parts=window.location.pathname.split('/').filter(Boolean);if(parts.length>0&&LANG_CODES.indexOf(parts[0])!==-1){return parts[0]}return'en'}function buildLangUrl(targetCode){var pathname=window.location.pathname;var parts=pathname.split('/').filter(Boolean);if(parts.length>0&&LANG_CODES.indexOf(parts[0])!==-1){parts.shift()}var newPath;if(targetCode==='en'){newPath='/'+parts.join('/');if(parts.length>0){newPath+='/'}}else{newPath='/'+targetCode+(parts.length>0?'/'+parts.join('/')+'/':'/')}return newPath+window.location.search+window.location.hash}function matchBrowserLang(browserLangs){for(var i=0;i<browserLangs.length;i++){var tag=browserLangs[i].toLowerCase();for(var j=0;j<LANGUAGES.length;j++){if(LANGUAGES[j].code.toLowerCase()===tag){return LANGUAGES[j].code}}var base=tag.split('-')[0];for(var k=0;k<LANGUAGES.length;k++){if(LANGUAGES[k].code.toLowerCase()===base){return LANGUAGES[k].code}}if(tag==='zh-tw'||tag==='zh-hk'||tag==='zh-mo'){return'zh-Hant'}if(tag==='zh-cn'||tag==='zh-sg'||tag==='zh'){return'zh-Hans'}}return null}var _liveLanguageCache=null;function getLiveLanguages(callback){if(_liveLanguageCache!==null){callback(_liveLanguageCache);return}var liveCodes=['en'];if(typeof fetch==='undefined'){_liveLanguageCache=LANGUAGES;callback(LANGUAGES);return}var nonEnglish=LANGUAGES.filter(function(l){return l.code!=='en'});var pending=nonEnglish.length;nonEnglish.forEach(function(lang){fetch('/'+lang.code+'/',{method:'HEAD'}).then(function(r){if(r.ok){liveCodes.push(lang.code)}}).catch(function(){}).finally(function(){pending--;if(pending===0){_liveLanguageCache=LANGUAGES.filter(function(l){return liveCodes.indexOf(l.code)!==-1});callback(_liveLanguageCache)}})})}function autoDetect(){var stored=localStorage.getItem(LANG_STORAGE_KEY);if(stored!==null){return}var currentLang=detectCurrentLang();localStorage.setItem(LANG_STORAGE_KEY,currentLang);if(currentLang!=='en'){return}var browserLangs=navigator.languages&&navigator.languages.length?Array.from(navigator.languages):[navigator.language||navigator.userLanguage||'en'];var matched=matchBrowserLang(browserLangs);if(matched&&matched!=='en'){getLiveLanguages(function(liveLanguages){var isLive=liveLanguages.some(function(l){return l.code===matched});if(isLive){localStorage.setItem(LANG_STORAGE_KEY,matched);window.location.replace(buildLangUrl(matched))}})}}function restorePreferredLang(){var currentLang=detectCurrentLang();if(currentLang!=='en'){return}if(isEnglishOnlyPage()){return}var stored=localStorage.getItem(LANG_STORAGE_KEY);if(!stored||stored==='en'){return}var translatedUrl=buildLangUrl(stored);if(typeof fetch==='undefined'){return}fetch(translatedUrl,{method:'HEAD'}).then(function(r){if(r.ok){window.location.replace(translatedUrl)}}).catch(function(){})}function fireGaEvent(fromLang,toLang){var consent=localStorage.getItem(CONSENT_KEY);if(consent!=='granted'){return}if(typeof window.gtag==='function'){window.gtag('event','language_switch',{from_lang:fromLang,to_lang:toLang})}}function switchLang(targetCode){var currentLang=detectCurrentLang();if(targetCode===currentLang){return}fireGaEvent(currentLang,targetCode);localStorage.setItem(LANG_STORAGE_KEY,targetCode);if(isEnglishOnlyPage()){window.location.href=targetCode==='en'?'/':'/'+targetCode+'/';return}var alt=document.querySelector('link[rel="alternate"][hreflang="'+targetCode+'"]');if(alt&&alt.href){window.location.href=alt.href;return}if(document.querySelector('link[rel="alternate"][hreflang]')){var isBlog=window.location.pathname.indexOf('/blog/')!==-1;if(targetCode==='en'){window.location.href=isBlog?'/blog/':'/'}else{window.location.href='/'+targetCode+(isBlog?'/blog/':'/')}return}window.location.href=buildLangUrl(targetCode)}function buildDropdownItem(lang,currentLang){var btn=document.createElement('button');btn.type='button';btn.setAttribute('role','option');btn.setAttribute('aria-selected',lang.code===currentLang?'true':'false');var isActive=lang.code===currentLang;btn.className=['flex items-center gap-2 w-full px-3 py-2 text-sm text-left transition-colors',isActive?'text-brand-gold bg-white/5 font-semibold':'text-slate-200 hover:text-white hover:bg-white/5'].join(' ');btn.innerHTML='<span aria-hidden="true">'+lang.flag+'</span>'+'<span>'+lang.name+'</span>'+(isActive?'<span class="ml-auto text-brand-gold text-xs" aria-hidden="true">\u2713</span>':'');btn.addEventListener('click',function(){switchLang(lang.code)});return btn}function buildMobileItem(lang,currentLang){var btn=document.createElement('button');btn.type='button';var isActive=lang.code===currentLang;btn.className=['flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm transition-colors',isActive?'bg-brand-gold/20 text-brand-gold font-semibold':'text-slate-200 hover:text-white hover:bg-white/5'].join(' ');btn.innerHTML='<span aria-hidden="true">'+lang.flag+'</span>'+'<span class="truncate">'+lang.name+'</span>';btn.addEventListener('click',function(){switchLang(lang.code)});return btn}function renderDesktopDropdown(dropdown,currentLang){dropdown.innerHTML='';LANGUAGES.forEach(function(lang){dropdown.appendChild(buildDropdownItem(lang,currentLang))})}function renderMobileList(container,currentLang){container.innerHTML='';LANGUAGES.forEach(function(lang){container.appendChild(buildMobileItem(lang,currentLang))})}function updateDesktopButton(currentLang){var flagEl=document.getElementById('lang-flag-desktop');var nameEl=document.getElementById('lang-name-desktop');if(!flagEl||!nameEl){return}var lang=LANGUAGES.find(function(l){return l.code===currentLang});if(!lang){return}flagEl.textContent=lang.flag;nameEl.textContent=lang.name}function positionDropdown(btn,dropdown){var rect=btn.getBoundingClientRect();dropdown.style.top=rect.bottom+6+'px';dropdown.style.left='auto';dropdown.style.right=window.innerWidth-rect.right+'px'}function initDesktopPicker(currentLang){var btn=document.getElementById('lang-btn-desktop');var placeholder=document.getElementById('lang-dropdown-desktop');if(!btn){return}var dropdown=document.createElement('div');dropdown.id='lang-dropdown-body';dropdown.setAttribute('role','listbox');dropdown.setAttribute('aria-label','Language selection');dropdown.style.cssText=['position: fixed','width: 13rem','max-height: 18rem','overflow-y: auto','z-index: 9999','border-radius: 0.75rem','border: 1px solid rgba(255,255,255,0.10)','background: rgba(17,25,40,0.92)','backdrop-filter: blur(12px)','-webkit-backdrop-filter: blur(12px)','box-shadow: 0 20px 40px rgba(0,0,0,0.5)','padding: 4px 0','display: none'].join(';');document.body.appendChild(dropdown);if(!document.getElementById('lang-picker-scrollbar-style')){var style=document.createElement('style');style.id='lang-picker-scrollbar-style';style.textContent=['#lang-dropdown-body::-webkit-scrollbar { width: 4px; }','#lang-dropdown-body::-webkit-scrollbar-track { background: transparent; }','#lang-dropdown-body::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.18); border-radius: 2px; }','#lang-dropdown-body::-webkit-scrollbar-thumb:hover { background: rgba(255,255,255,0.32); }','#lang-dropdown-body { scrollbar-width: thin; scrollbar-color: rgba(255,255,255,0.18) transparent; }'].join('\n');document.head.appendChild(style)}if(placeholder){placeholder.remove()}updateDesktopButton(currentLang);var populated=false;function populate(){if(populated){return}populated=true;getLiveLanguages(function(liveLanguages){dropdown.innerHTML='';liveLanguages.forEach(function(lang){dropdown.appendChild(buildDropdownItem(lang,currentLang))});positionDropdown(btn,dropdown)})}function openDropdown(){populate();positionDropdown(btn,dropdown);dropdown.style.display='block';btn.setAttribute('aria-expanded','true')}function closeDropdown(){dropdown.style.display='none';btn.setAttribute('aria-expanded','false')}function isOpen(){return dropdown.style.display!=='none'}btn.addEventListener('click',function(e){e.stopPropagation();if(isOpen()){closeDropdown()}else{openDropdown()}});window.addEventListener('scroll',function(){if(isOpen()){positionDropdown(btn,dropdown)}},{passive:true});window.addEventListener('resize',function(){if(isOpen()){positionDropdown(btn,dropdown)}});document.addEventListener('click',function(){if(isOpen()){closeDropdown()}});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&isOpen()){closeDropdown();btn.focus()}})}function initMobilePicker(currentLang){var container=document.getElementById('lang-mobile-list');if(!container){return}var populated=false;function populate(){if(populated){return}populated=true;getLiveLanguages(function(liveLanguages){container.innerHTML='';liveLanguages.forEach(function(lang){container.appendChild(buildMobileItem(lang,currentLang))})})}var menuButton=document.getElementById('mobile-menu-button');if(menuButton){menuButton.addEventListener('click',populate,{once:true})}else{populate()}}function getPreferredDisplayLang(){var currentLang=detectCurrentLang();if(currentLang!=='en'){return currentLang}if(isEnglishOnlyPage()){return'en'}var stored=localStorage.getItem(LANG_STORAGE_KEY);return stored&&stored!=='en'?stored:'en'}function rewriteNavLinksForPreferredLang(){if(detectCurrentLang()!=='en'){return}var stored=localStorage.getItem(LANG_STORAGE_KEY);if(!stored||stored==='en'){return}if(LANG_CODES.indexOf(stored)===-1){return}var prefix='/'+stored;var translatablePaths=['/','/features/','/faq/','/why-us/','/blog/','/accessibility/','/#pricing'];var origin=window.location.origin;var links=document.querySelectorAll('a[href]');for(var i=0;i<links.length;i++){var a=links[i];var resolved=a.href;if(!resolved||resolved.indexOf(origin)!==0){continue}var path=resolved.replace(origin,'')+(a.hash&&resolved.indexOf(a.hash)===-1?a.hash:'');if(path.indexOf(prefix+'/')===0||path===prefix){continue}for(var j=0;j<translatablePaths.length;j++){var tp=translatablePaths[j];if(path===tp){a.href=prefix+tp;break}}if(path.indexOf('/blog/why-i-built-travel-document-vault')!==-1){a.href=prefix+'/blog/why-i-built-travel-document-vault/'}}}function init(){autoDetect();restorePreferredLang();rewriteNavLinksForPreferredLang();var displayLang=getPreferredDisplayLang();initDesktopPicker(displayLang);initMobilePicker(displayLang)}if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',init)}else{init()}}())